export function setupBrushDetails({pane,presets,builtins,preview,persist,presetsChanged}){
 const $=id=>document.getElementById(id),select=$('brushPreset'),trigger=pane.querySelector('.brush-advanced'),dialog=document.createElement('dialog');dialog.id='brushDetailDialog';dialog.className='brush-detail-dialog';
 dialog.innerHTML='<header><h2>브러시 상세 설정</h2><button type="button" aria-label="브러시 상세 설정 닫기">✕</button></header><div class="brush-detail-layout"><nav aria-label="브러시 설정 종류"></nav><div class="brush-detail-fields"></div></div><footer><input id="brushPresetName" aria-label="새 브러시 이름" placeholder="새 브러시 이름"><button id="brushSaveCopy">복제 저장</button><button id="brushSaveDefault">기본값 저장</button><button id="brushResetDefault">기본값 복원</button><button id="brushRemovePreset">브러시 삭제</button></footer><p id="brushDetailStatus" role="status"></p>';
 document.body.append(dialog);const open=document.createElement('button');open.type='button';open.id='brushDetailOpen';open.title='브러시 상세 설정';open.setAttribute('aria-label','브러시 상세 설정');open.innerHTML=wrench;trigger.append(open);open.onclick=()=>{sync();dialog.showModal();};dialog.querySelector('header button').onclick=()=>dialog.close();
 let defaults={},drafts={},basics={};try{basics=JSON.parse(localStorage.getItem('scroll-brush-basics')||'{}');for(const p of presets)if(basics[p.name])Object.assign(p,basics[p.name]);}catch{}try{defaults=JSON.parse(localStorage.getItem('scroll-brush-defaults')||'{}');}catch{}
 const key=()=>presets[+select.value]?.name||'브러시';const read=()=>drafts[key()]??defaults[key()]??presets[+select.value]?.brushSettings??null;
 const groups=[
 ['필압 · 크기',[['minSize','최소 크기 %',0,100],['pressureCurve','필압 곡선',.2,4,.05],['tiltSize','기울기에 따른 크기 %',0,100],['velocitySize','빠른 획 크기 감소 %',0,100]]],
 ['잉크',[['opacityPressure','필압으로 불투명도','check'],['density','팁 밀도 %',1,100],['blend','브러시 합성',{ 'source-over':'표준',multiply:'곱하기',screen:'스크린',overlay:'오버레이',darken:'비교(어두움)',lighten:'비교(밝음)','color-dodge':'색상 닷지','color-burn':'색상 번','hard-light':'하드 라이트','soft-light':'소프트 라이트',difference:'차이',exclusion:'제외',hue:'색조',saturation:'채도',color:'컬러',luminosity:'휘도',lighter:'더하기'}]]],
 ['브러시 끝',[['tip','팁 모양',{round:'원형',square:'사각 팁',diamond:'마름모 팁',image:'불러온 이미지 팁'}],['roundness','두께 %',2,100],['angle','각도 °',-180,180],['followDirection','선 방향으로 회전','check']]],
 ['스트로크',[['spacing','팁 간격 %',1,300],['continuousSpray','누르고 있을 때 연속 분사','check'],['sprayRate','연속 분사 / 초',1,60],['taperStart','시작 가늘게 %',0,100],['taperEnd','끝 가늘게 %',0,100]]],
 ['분사 · 무작위',[['sprayFootprint','브러시 원 안에 분사','check'],['particleSize','입자 크기 %',1,100],['scatter','분사 범위 %',0,300],['particles','입자 수',1,32],['sizeJitter','크기 무작위 %',0,100],['angleJitter','각도 무작위 °',0,180]]],
 ['색 변화',[['hueJitter','색상 변화 %',0,100],['saturationJitter','채도 변화 %',0,100],['valueJitter','명도 변화 %',0,100]]],
 ['질감',[['texture','질감',{none:'없음',paper:'종이 입자',grid:'격자',hatch:'사선'}],['textureDepth','농도 %',0,100],['textureScale','크기',2,200],['textureAngle','회전 °',-180,180],['textureInvert','질감 반전','check']]],
 ['듀얼 브러시',[['dual','두 번째 팁 사용','check'],['dualSize','두 번째 팁 크기 %',5,200],['dualAngle','두 번째 팁 각도 °',-180,180],['dualMode','두 번째 팁 합성',{'destination-in':'겹치는 부분','destination-out':'두 번째 팁으로 깎기','source-over':'두 팁 합치기'}]]],
 ['가장자리',[['edge','수채 가장자리 폭 %',0,30],['edgeDarkness','가장자리 어둡기 %',0,100]]],
 ['보정 · 지우기',[['postCorrection','획 완료 후 보정 %',0,100],['antiOverflow','참조 선 안쪽만 칠하기','check'],['vectorErase','벡터 지우기',{none:'사용 안 함',stroke:'닿은 벡터 획 전체'}]]],
 ['입력 · 가져오기',[]]
 ];
 const fields=dialog.querySelector('.brush-detail-fields'),nav=dialog.querySelector('nav'),inputs=new Map(),panels=[];
 for(const [index,[name,rows]]of groups.entries()){const tab=document.createElement('button');tab.type='button';tab.textContent=name;tab.setAttribute('aria-pressed',String(index===0));nav.append(tab);const section=document.createElement('section');section.hidden=index!==0;section.innerHTML='<h3></h3>';section.firstChild.textContent=name;fields.append(section);panels.push(section);tab.onclick=()=>{panels.forEach((p,i)=>p.hidden=i!==index);[...nav.children].forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));};
  for(const [id,label,min,max,step]of rows){const row=document.createElement('label'),text=document.createElement('span');text.textContent=label;row.append(text);let input;
   if(typeof min==='object'){input=document.createElement('select');for(const [v,n]of Object.entries(min))input.add(new Option(n,v));}else{input=document.createElement('input');input.type=min==='check'?'checkbox':'range';if(min!=='check'){input.min=min;input.max=max;input.step=step||1;}}
   input.id='brushDetail-'+id;input.setAttribute('aria-label',label);row.append(input);if(input.type==='range'){const out=document.createElement('output');out.setAttribute('for',input.id);row.append(out);}section.append(row);inputs.set(id,input);input.oninput=()=>{const b=normalizeBrush(read()||{});b[id]=input.type==='checkbox'?input.checked:input.type==='range'?+input.value:input.value;drafts[key()]=normalizeBrush(b);syncValues();preview();};
  }
 }
 const pressure=$('brushPressure').closest('label'),hardness=$('brushHardness').closest('label');panels[0].append(pressure);panels[2].append(hardness);
 const graph=document.createElement('canvas');graph.id='brushPressureGraph';graph.width=240;graph.height=120;graph.setAttribute('aria-label','필압 입력과 브러시 크기 곡선');panels[0].append(graph);const note=document.createElement('small');note.textContent='가로: 펜 압력 · 세로: 크기. 마우스는 압력 100%, 기울기 0으로 처리됩니다.';panels[0].append(note);
 for(const el of [...pane.querySelectorAll('.drawing-assist-options,#importBrush,#brushFile,#brushNotice')])panels.at(-1).append(el);pane.querySelector('.drawing-shapes')?.remove();trigger.replaceChildren(open);
 for(const [index,id,label]of [[2,'tipImage','팁 이미지 불러오기'],[6,'textureImage','질감 이미지 불러오기']]){const button=document.createElement('button'),file=document.createElement('input');button.type='button';button.textContent=label;file.type='file';file.accept='image/png,image/jpeg,image/webp';file.hidden=true;panels[index].append(button,file);button.onclick=()=>file.click();file.onchange=async()=>{const f=file.files[0];if(!f)return;try{if(f.size>8*1024*1024)throw Error('8MB 이하 이미지를 선택하세요.');const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);}),im=await loadBitmap(src),cv=document.createElement('canvas'),scale=Math.min(1,512/Math.max(im.width,im.height));cv.width=Math.max(1,Math.round(im.width*scale));cv.height=Math.max(1,Math.round(im.height*scale));cv.getContext('2d').drawImage(im,0,0,cv.width,cv.height);const cx=cv.getContext('2d'),pix=cx.getImageData(0,0,cv.width,cv.height);for(let i=0;i<pix.data.length;i+=4){const dark=1-(pix.data[i]+pix.data[i+1]+pix.data[i+2])/765;pix.data[i+3]*=dark;pix.data[i]=pix.data[i+1]=pix.data[i+2]=255;}cx.putImageData(pix,0,0);const data=cv.toDataURL('image/png');rememberBitmap(data,cv);const b=normalizeBrush(read()||{});b[id]=data;if(id==='tipImage')b.tip='image';drafts[key()]=b;sync();preview();$('brushDetailStatus').textContent=f.name+' · 검은 부분을 팁/질감으로 변환했습니다.';}catch(e){$('brushDetailStatus').textContent=e.message;}file.value='';};const clear=document.createElement('button');clear.textContent='이미지 제거';clear.onclick=()=>{const b=normalizeBrush(read()||{});b[id]='';if(id==='tipImage')b.tip='round';drafts[key()]=b;sync();preview();};panels[index].append(clear);}
 function syncValues(){const b=normalizeBrush(read()||{});for(const [id,input]of inputs){if(input.type==='checkbox')input.checked=b[id];else input.value=b[id];const out=input.nextElementSibling;if(out?.tagName==='OUTPUT')out.textContent=input.value;}inputs.get('postCorrection').disabled=b.continuousSpray;inputs.get('postCorrection').title=b.continuousSpray?'연속 분사에서는 획 완료 후 보정을 사용하지 않습니다.':'';const ctx=graph.getContext('2d');ctx.fillStyle='#14181c';ctx.fillRect(0,0,240,120);ctx.strokeStyle='#46515b';ctx.lineWidth=1;ctx.beginPath();for(let i=0;i<=4;i++){ctx.moveTo(10+i*55,10);ctx.lineTo(10+i*55,110);ctx.moveTo(10,10+i*25);ctx.lineTo(230,10+i*25);}ctx.stroke();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();for(let x=0;x<=220;x++){const y=110-100*(b.minSize/100+(1-b.minSize/100)*Math.pow(x/220,b.pressureCurve));x?ctx.lineTo(10+x,y):ctx.moveTo(10+x,y);}ctx.stroke();}
 function sync(){const b=read();if(b)Promise.all([b.tipImage,b.textureImage].filter(Boolean).map(loadBitmap)).then(preview).catch(e=>$('brushDetailStatus').textContent=e.message);dialog.querySelector('h2').textContent=key()+' · 상세 설정';$('brushRemovePreset').disabled=+select.value<builtins;syncValues();}
 function storeDefaults(){localStorage.setItem('scroll-brush-defaults',JSON.stringify(defaults));}
 $('brushSaveDefault').onclick=()=>{defaults[key()]=normalizeBrush(read()||{});Object.assign(presets[+select.value],{size:+$('penSize').value,opacity:+$('brushOpacity').value,hardness:+$('brushHardness').value,smoothing:+$('brushSmoothing').value,pressure:$('brushPressure').checked,antialias:$('penAntialias').value,brushSettings:defaults[key()]});basics[key()]={size:+$('penSize').value,opacity:+$('brushOpacity').value,hardness:+$('brushHardness').value,smoothing:+$('brushSmoothing').value,pressure:$('brushPressure').checked,antialias:$('penAntialias').value};localStorage.setItem('scroll-brush-basics',JSON.stringify(basics));persist();storeDefaults();presetsChanged();$('brushDetailStatus').textContent='이 브러시의 기본값을 저장했습니다.';};
 $('brushResetDefault').onclick=()=>{delete drafts[key()];const p=presets[+select.value];for(const [id,k]of [['penSize','size'],['brushOpacity','opacity'],['brushHardness','hardness'],['brushSmoothing','smoothing']])$(id).value=p[k];$('brushPressure').checked=p.pressure!==false;$('penAntialias').value=p.antialias||'middle';sync();preview();$('brushDetailStatus').textContent='저장한 기본값으로 복원했습니다.';};
 $('brushSaveCopy').onclick=()=>{const name=$('brushPresetName').value.trim();if(!name){$('brushDetailStatus').textContent='저장할 브러시 이름을 입력하세요.';return;}if(presets.some(p=>p.name===name)){$('brushDetailStatus').textContent='다른 브러시 이름을 입력하세요.';return;}presets.push({...presets[+select.value],name,size:+$('penSize').value,opacity:+$('brushOpacity').value,hardness:+$('brushHardness').value,smoothing:+$('brushSmoothing').value,pressure:$('brushPressure').checked,antialias:$('penAntialias').value,brushSettings:normalizeBrush(read()||{})});select.add(new Option(name,String(presets.length-1)));select.value=String(presets.length-1);select.dispatchEvent(new Event('change'));persist();sync();$('brushDetailStatus').textContent='새 브러시를 저장했습니다.';};
 $('brushRemovePreset').onclick=()=>{const i=+select.value;if(i<builtins)return;delete defaults[key()];delete drafts[key()];delete basics[key()];localStorage.setItem('scroll-brush-basics',JSON.stringify(basics));presets.splice(i,1);select.replaceChildren(...presets.map((p,j)=>new Option(p.name,String(j))));select.value='0';select.dispatchEvent(new Event('change'));persist();storeDefaults();sync();$('brushDetailStatus').textContent='사용자 브러시를 삭제했습니다.';};
 select.addEventListener('change',sync);return {read:()=>read()?normalizeBrush(read()):undefined,sync};
}
